      "solutionCode": "public class HouseRobber {\n\n    public int rob(int[] nums) {\n        if (nums.length == 0) {\n            return 0;\n        }\n        if (nums.length == 1) {\n            return nums[0];\n        }\n        int prev2 = nums[0];\n        int prev1 = Math.max(nums[0], nums[1]);\n        for (int i = 2; i < nums.length; i++) {\n            int current = Math.max(prev1, prev2 + nums[i]);\n            prev2 = prev1;\n            prev1 = current;\n        }\n        return prev1;\n    }\n}",
