      "runCommand": "java -cp target/classes com.john.algorithm.sorting.medium.SortColors",
      "solutionCode": "public class SortColors {\n\n    public void sortColors(int[] nums) {\n        int p0 = 0;\n        int p2 = nums.length - 1;\n        int i = 0;\n        while (i <= p2) {\n            if (nums[i] == 0) {\n                swap(nums, i, p0);\n                p0++;\n                i++;\n            } else if (nums[i] == 2) {\n                swap(nums, i, p2);\n                p2--;\n            } else {\n                i++;\n            }\n        }\n    }\n\n    private void swap(int[] nums, int i, int j) {\n        int temp = nums[i];\n        nums[i] = nums[j];\n        nums[j] = temp;\n    }\n}",
