      "solutionCode": "public class RedundantConnectionII {\n\n    public int[] findRedundantDirectedEdge(int[][] edges) {\n        int n = edges.length;\n        int[] firstParentEdge = new int[n + 1];\n        int cand1 = -1;\n        int cand2 = -1;\n        for (int i = 0; i < n; i++) {\n            int child = edges[i][1];\n            if (firstParentEdge[child] != 0) {\n                cand1 = firstParentEdge[child] - 1;\n                cand2 = i;\n            } else {\n                firstParentEdge[child] = i + 1;\n            }\n        }\n        int[] uf = new int[n + 1];\n        for (int i = 0; i <= n; i++) {\n            uf[i] = i;\n        }\n        for (int i = 0; i < n; i++) {\n            if (i == cand1) {\n                continue;\n            }\n            int u = edges[i][0];\n            int v = edges[i][1];\n            if (find(uf, u) == find(uf, v)) {\n                return cand2 == -1 ? edges[i] : edges[cand1];\n            }\n            union(uf, u, v);\n        }\n        return edges[cand2];\n    }\n\n    private int find(int[] uf, int x) {\n        if (uf[x] != x) {\n            uf[x] = find(uf, uf[x]);\n        }\n        return uf[x];\n    }\n\n    private void union(int[] uf, int u, int v) {\n        uf[find(uf, u)] = find(uf, v);\n    }\n}",
