      "solutionCode": "public class NumberOfProvinces {\n\n    public int findCircleNum(int[][] isConnected) {\n        int n = isConnected.length;\n        UnionFind unionFind = new UnionFind(n);\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j < n; j++) {\n                if (isConnected[i][j] == 1) {\n                    unionFind.union(i, j);\n                }\n            }\n        }\n        return unionFind.count;\n    }\n\n    private static class UnionFind {\n        private final int[] parent;\n        private int count;\n\n        UnionFind(int n) {\n            parent = new int[n];\n            count = n;\n            for (int i = 0; i < n; i++) {\n                parent[i] = i;\n            }\n        }\n\n        int find(int x) {\n            if (parent[x] != x) {\n                parent[x] = find(parent[x]);\n            }\n            return parent[x];\n        }\n\n        void union(int x, int y) {\n            int rootX = find(x);\n            int rootY = find(y);\n            if (rootX == rootY) {\n                return;\n            }\n            parent[rootX] = rootY;\n            count--;\n        }\n    }\n}",
